// reducer 风格 store：纯函数 dispatch(action) -> 新状态；不依赖浏览器与框架
function createStore(reducer, initialState) {
  let state = initialState;
  const listeners = [];
  return {
    getState: () => state,
    dispatch(action) {
      const next = reducer(state, action);
      if (next === state) return state;       // 状态未变 -> 不通知订阅者
      state = next;
      for (const l of listeners) l(state);
      return state;
    },
    subscribe(l) { listeners.push(l); return () => listeners.splice(listeners.indexOf(l), 1); },
  };
}

const initial = { todos: [], filter: 'all' };

function reducer(state, action) {
  switch (action.type) {
    case 'ADD':
      return { ...state, todos: [...state.todos, { id: action.id, text: action.text, done: false }] };
    case 'TOGGLE':
      return { ...state, todos: state.todos.map(t => t.id === action.id ? { ...t, done: !t.done } : t) };
    case 'SET_FILTER':
      return { ...state, filter: action.filter };
    default:
      return state;                            // 未知 action 保持引用不变（identity 稳定）
  }
}

function selectVisible(state) {
  if (state.filter === 'all') return state.todos;
  if (state.filter === 'done') return state.todos.filter(t => t.done);
  return state.todos.filter(t => !t.done);
}

const store = createStore(reducer, initial);
let renders = 0;
store.subscribe(() => { renders += 1; });

store.dispatch({ type: 'ADD', id: 1, text: 'write docs' });
store.dispatch({ type: 'ADD', id: 2, text: 'ship app' });
store.dispatch({ type: 'TOGGLE', id: 1 });
console.log('renders_after_3_actions=' + renders);

const snap1 = store.getState();
store.dispatch({ type: 'UNKNOWN' });
console.log('unknown_action_keeps_identity=' + (store.getState() === snap1));
console.log('renders_after_noop_action=' + renders);

store.dispatch({ type: 'SET_FILTER', filter: 'active' });
console.log('active_count=' + selectVisible(store.getState()).length);
console.log('done_count=' + store.getState().todos.filter(t => t.done).length);
console.log('todos_total=' + store.getState().todos.length);
